import { Product, Category } from './types';
import catalog from './catalog.json';
import { isDemoMode } from './config';

// =========================================================================
// Каталог лавки собран из прайса поставщика «Прайс 0711.xlsx» (выгрузка 1С).
// Единственный источник названий, цен и групп — прайс: lib/catalog.json
// regenerated by scripts/build-catalog.mjs. Позиции без цены в прайсе не
// продаются: они уходят в PREVIEWS и показываются как «уточнить в лавке».
// ИНТЕГРАЦИЯ 1С: см. getProducts() в конце файла.
// =========================================================================

export type CatalogCategory = { cat: Category; title: string; short: string; note: string };
export type CatalogKit = { id: string; label: string; title: string; description: string; items: { productId: string; packIdx: number }[] };

interface CatalogItem {
  id: string;
  code: string;
  title: string;
  category: Category;
  agingMonths: number | null;
  description: string;
  image: string | null;
  imageCaption?: string;
  imageW?: number | null;
  imageH?: number | null;
  kind?: 'piece' | 'pack';
  pricePerKg?: number;
  pieces?: Product['pieces'];
  packs?: Product['packs'];
  bulk?: Product['bulk'];
}

const entries = catalog as unknown as {
  categories: CatalogCategory[];
  kits: CatalogKit[];
  products: CatalogItem[];
  previews: CatalogItem[];
};

// Группы и наборы приходят из прайса вместе с товарами: обе витрины читают один источник.
export const CATEGORY_TITLES = Object.fromEntries(
  entries.categories.map((category) => [category.cat, { title: category.title, short: category.short, note: category.note }]),
) as Record<Category, { title: string; short: string; note: string }>;

export const DEPT_ORDER: { cat: Category; id: string }[] = entries.categories.map((category) => ({ cat: category.cat, id: `dept-${category.cat}` }));

export const CATEGORIES: Category[] = entries.categories.map((category) => category.cat);

export const KITS = entries.kits;

const toProduct = (entry: CatalogItem): Product => ({
  id: entry.id,
  code: entry.code,
  category: entry.category,
  title: entry.title,
  agingMonths: entry.agingMonths,
  description: entry.description,
  kind: entry.kind ?? 'pack',
  pricePerKg: entry.pricePerKg ?? 0,
  pieces: entry.pieces ?? [],
  packs: entry.packs ?? [],
  bulk: entry.bulk ?? null,
  imageUrl: entry.image ? `/${entry.image}` : undefined,
  imageCaption: entry.imageCaption,
  imageW: entry.imageW ?? undefined,
  imageH: entry.imageH ?? undefined,
});

export const PRODUCTS: Product[] = entries.products.map(toProduct);

export interface CatalogPreview {
  id: string;
  code: string;
  category: Category;
  title: string;
  agingMonths: number | null;
  description: string;
  imageUrl?: string;
  imageCaption?: string;
}

export const PREVIEWS: CatalogPreview[] = entries.previews.map((entry) => ({
  id: entry.id,
  code: entry.code,
  category: entry.category,
  title: entry.title,
  agingMonths: entry.agingMonths,
  description: entry.description,
  imageUrl: entry.image ? `/${entry.image}` : undefined,
  imageCaption: entry.imageCaption,
  imageW: entry.imageW ?? undefined,
  imageH: entry.imageH ?? undefined,
}));

export function averageWeightOf(product: Product): number {
  return product.pieces.length
    ? Math.round(product.pieces.reduce((sum, piece) => sum + piece.weightG, 0) / product.pieces.length)
    : 0;
}

export function piecePriceOf(product: Product, weightG: number, fixedPrice?: number): number {
  if (typeof fixedPrice === 'number') return fixedPrice;
  return Math.round((weightG / 1000) * product.pricePerKg);
}

export function calcPricePer100g(pricePerKg: number): number {
  return Math.round(pricePerKg / 10);
}

// =========================================================================
// ИНТЕГРАЦИЯ 1С:УНФ 3.0
// Если задан ONEC_API_URL — получаем каталог оттуда (формат тот же, что PRODUCTS).
// Пока переменной нет — работает каталог, собранный из прайса.
// =========================================================================
function validCatalog(value: unknown): value is Product[] {
  if (!Array.isArray(value)) return false;
  const ids = new Set<string>();
  const pieceIds = new Set<string>();
  const money = (amount: unknown) => typeof amount === 'number' && Number.isSafeInteger(amount) && amount >= 0;
  const positive = (amount: unknown) => money(amount) && Number(amount) > 0;
  return value.every((p) => {
    if (!p || typeof p !== 'object' || typeof p.id !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9_.-]{0,99}$/.test(p.id)
      || ids.has(p.id) || typeof p.code !== 'string' || !CATEGORIES.includes(p.category)
      || !['piece', 'pack'].includes(p.kind) || typeof p.title !== 'string' || !p.title.trim()
      || typeof p.description !== 'string' || !money(p.pricePerKg)
      || !(p.agingMonths === null || positive(p.agingMonths)) || !Array.isArray(p.pieces) || !Array.isArray(p.packs)) return false;
    ids.add(p.id);
    if (!p.pieces.every((piece: Product['pieces'][number]) => {
      if (!piece || typeof piece.id1c !== 'string' || !piece.id1c || pieceIds.has(piece.id1c) || !positive(piece.weightG) || !(piece.price === undefined || positive(piece.price))) return false;
      pieceIds.add(piece.id1c);
      return true;
    })) return false;
    if (!p.packs.every((pack: Product['packs'][number]) => pack && typeof pack.label === 'string' && money(pack.weightG) && positive(pack.price))) return false;
    if (p.kind === 'pack' && !p.packs.length) return false;
    if (p.kind === 'piece' && !positive(p.pricePerKg)) return false;
    if (p.bulk !== null && (!p.bulk || !positive(p.bulk.minG) || !positive(p.bulk.maxG) || p.bulk.maxG < p.bulk.minG || !positive(p.bulk.stepG) || !positive(p.bulk.pricePerKg))) return false;
    if (p.imageUrl !== undefined && (typeof p.imageUrl !== 'string' || !(/^https:\/\//.test(p.imageUrl) || /^\/(?!\/)/.test(p.imageUrl)))) return false;
    if (p.imageCaption !== undefined && typeof p.imageCaption !== 'string') return false;
    return true;
  });
}

if (!validCatalog(PRODUCTS)) throw new Error('lib/catalog.json does not match the catalog contract');

export async function getProducts(): Promise<Product[]> {
  if (isDemoMode()) return PRODUCTS;
  const url = process.env.ONEC_API_URL;
  if (!url) throw new Error('Live catalog is not configured');
  const response = await fetch(url, {
    headers: process.env.ONEC_TOKEN ? { Authorization: `Bearer ${process.env.ONEC_TOKEN}` } : {},
    cache: 'no-store',
    signal: AbortSignal.timeout(10000),
  });
  if (!response.ok) throw new Error(`Catalog service responded ${response.status}`);
  const data: unknown = await response.json();
  const list = Array.isArray(data) ? data : data && typeof data === 'object' && 'products' in data ? data.products : undefined;
  if (!validCatalog(list)) throw new Error('Catalog service returned invalid product data');
  return list;
}
